import{_ as t,o as a,c as e,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-03","description":"","frontmatter":{"date":"2026-08-03T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-03-uxtrend.md","filePath":"daily/2026-08-03-uxtrend.md"}'),n={name:"daily/2026-08-03-uxtrend.md"};function s(i,r,g,p,h,d){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-03" tabindex="-1">设计趋势 - 2026-08-03 <a class="header-anchor" href="#设计趋势-2026-08-03" aria-label="Permalink to &quot;设计趋势 - 2026-08-03&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于人工智能与用户体验的融合。主要动态包括代理UX设计原则、建立人机信任、AI工作流设计超越对话界面、以及用户体验2.0的代理体验设计。最值得关注的是人工智能时代下的用户体验2.0，它要求设计超越界面，融入逻辑、伦理和行为，以及Figma中AI工作流对创意流程的影响。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨了设计新型数字设备用户体验的代理UX设计原则。</p><p><strong>能解决什么问题</strong>: 解决数字代理系统在用户体验设计中的独特挑战。</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速开发并强调AI中的人本原则。</p><p><strong>示例场景</strong>: 设计一个能够协助团队协作和提升个人能力的AI代理系统。</p><hr><h3 id="_2-人工智能时代的agentic-ux设计" tabindex="-1">2. 人工智能时代的Agentic UX设计 <a class="header-anchor" href="#_2-人工智能时代的agentic-ux设计" aria-label="Permalink to &quot;2. 人工智能时代的Agentic UX设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Agentic UX设计关注于在人机之间建立信任。</p><p><strong>能解决什么问题</strong>: 解决AI代理在企业系统中如何被接受的问题。</p><p><strong>产品应用</strong>: 适用于智能系统设计，通过设计原则提升用户体验。</p><p><strong>示例场景</strong>: 在金融科技中，AI代理帮助用户做出投资决策。</p><hr><h3 id="_3-ai工作流设计规则-超越对话界面" tabindex="-1">3. AI工作流设计规则：超越对话界面 <a class="header-anchor" href="#_3-ai工作流设计规则-超越对话界面" aria-label="Permalink to &quot;3. AI工作流设计规则：超越对话界面&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI工作流设计应基于功能而非模拟人类角色。</p><p><strong>能解决什么问题</strong>: AI系统因设计错误导致失败，而非模型问题。</p><p><strong>产品应用</strong>: 适用于任何需要AI自动化流程的产品，直接嵌入功能。</p><p><strong>示例场景</strong>: 自动化客户服务系统，无需模拟人类助手。</p><hr><h3 id="_4-人工智能时代下的用户体验2-0-代理体验设计" tabindex="-1">4. 人工智能时代下的用户体验2.0：代理体验设计 <a class="header-anchor" href="#_4-人工智能时代下的用户体验2-0-代理体验设计" aria-label="Permalink to &quot;4. 人工智能时代下的用户体验2.0：代理体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 在人工智能代理时代，用户体验设计需超越界面，融入逻辑、伦理和行为。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的体验设计问题，提升人机交互的无缝性。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人协作的产品，如自动化客服、智能助手等。</p><p><strong>示例场景</strong>: AI代理帮助用户预约医生，提升预约流程的效率和准确性。</p><hr><h3 id="_5-figma中的ai工作流-图像、视频与创意生成" tabindex="-1">5. Figma中的AI工作流：图像、视频与创意生成 <a class="header-anchor" href="#_5-figma中的ai工作流-图像、视频与创意生成" aria-label="Permalink to &quot;5. Figma中的AI工作流：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: Figma社区提供的AI工作流帮助用户结构化创意流程。</p><p><strong>能解决什么问题</strong>: 解决AI创意工具使用中模型选择和结果一致性的难题。</p><p><strong>产品应用</strong>: 可应用于产品设计、营销、品牌建设等多个领域。</p><p><strong>示例场景</strong>: 使用AI工作流为营销活动生成视觉内容。</p><hr><h3 id="_6-2026年设计师现状-ai提升设计质量" tabindex="-1">6. 2026年设计师现状：AI提升设计质量 <a class="header-anchor" href="#_6-2026年设计师现状-ai提升设计质量" aria-label="Permalink to &quot;6. 2026年设计师现状：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 91%的设计师认为AI提高了设计质量而非仅速度。</p><p><strong>能解决什么问题</strong>: AI辅助设计提升效率和质量，但需人工完成精细调整。</p><p><strong>产品应用</strong>: 应用于产品设计，AI辅助早期设计，人工完成后期细节。</p><p><strong>示例场景</strong>: 设计师使用AI生成原型，再进行人工优化。</p><hr><h3 id="_7-确定ai干预的时机" tabindex="-1">7. 确定AI干预的时机 <a class="header-anchor" href="#_7-确定ai干预的时机" aria-label="Permalink to &quot;7. 确定AI干预的时机&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@krithika_bala/designing-ai-assisted-workflows-871facbc694f" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI应增强人的能力而非取代之。</p><p><strong>能解决什么问题</strong>: 如何将AI智能融入工作流程中，提升效率。</p><p><strong>产品应用</strong>: 可应用于需要自动化和增强决策的场景。</p><p><strong>示例场景</strong>: 企业文档处理流程中的AI辅助。</p><hr><h3 id="_8-ai如何成为设计师的倍增器" tabindex="-1">8. AI如何成为设计师的倍增器 <a class="header-anchor" href="#_8-ai如何成为设计师的倍增器" aria-label="Permalink to &quot;8. AI如何成为设计师的倍增器&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@surdattack/how-ai-is-influencing-todays-design-workflows-in-conversation-with-a-young-designer-ac6810b9cfd5" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 设计师通过AI提升创造力，专注于策略和同理心设计</p><p><strong>能解决什么问题</strong>: 设计师如何利用AI处理繁琐任务，释放创造力</p><p><strong>产品应用</strong>: 可应用于产品设计流程，AI处理数据和原型，设计师专注策略</p><p><strong>示例场景</strong>: 设计师利用AI进行大规模数据分析，快速迭代设计</p><hr><h3 id="_9-ai和llms在设计代理工作流中的新挑战与机遇" tabindex="-1">9. AI和LLMs在设计代理工作流中的新挑战与机遇 <a class="header-anchor" href="#_9-ai和llms在设计代理工作流中的新挑战与机遇" aria-label="Permalink to &quot;9. AI和LLMs在设计代理工作流中的新挑战与机遇&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/google-cloud/designing-cognitive-architectures-agentic-workflow-patterns-from-scratch-63baa74c54bc" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI和LLMs的快速发展为设计智能代理工作流带来了新挑战和机遇。</p><p><strong>能解决什么问题</strong>: 解决如何构建复杂、自适应的AI系统以应对多样化的实际问题。</p><p><strong>产品应用</strong>: 可应用于实际产品，通过应用这些模式提升AI系统的效率和自适应能力。</p><p><strong>示例场景</strong>: 在多任务协作中，通过任务协调模式实现不同AI代理间的无缝合作。</p><hr><h3 id="_10-产品设计师的ai工作流程金字塔" tabindex="-1">10. 产品设计师的AI工作流程金字塔 <a class="header-anchor" href="#_10-产品设计师的ai工作流程金字塔" aria-label="Permalink to &quot;10. 产品设计师的AI工作流程金字塔&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://heyakash.medium.com/the-ai-workflow-pyramid-for-product-designers-df5d50d19963" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI正在改变产品设计工作流程。</p><p><strong>能解决什么问题</strong>: 设计师如何有效利用AI进行产品设计。</p><p><strong>产品应用</strong>: 可以，通过构建AI驱动的工作流程来优化设计过程。</p><p><strong>示例场景</strong>: 使用AI工具进行用户研究和原型设计。</p><hr>',75)])])}const m=t(n,[["render",s]]);export{c as __pageData,m as default};
